import { Group, PlaneGeometry, MeshBasicNodeMaterial, Mesh } from 'three/webgpu';
import { gsap } from 'gsap';

/**
 * Creates a hero headline node: a textured plane with overlaid body text.
 * @param {import('@/prism').PrismNode} config
 * @param {import('@/prism').NodeContext} ctx
 * @returns {import('three/webgpu').Object3D}
 */
export default function createNode(config, ctx) {
  const { userData = {} } = config;
  const group = new Group();

  // --- Text content ---
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const bodyItem = items.find(item => item.role === 'body') || items[0];
  const bodyText = bodyItem?.text || '';

  // --- Placeholder gradient plane (will be replaced by texture) ---
  const planeWidth = 5.0;  // scene units
  const planeHeight = 3.125; // matches texture aspect ratio (512x320 ~ 1.6:1)
  const geometry = new PlaneGeometry(planeWidth, planeHeight);
  const material = new MeshBasicNodeMaterial({
    color: config.colors?.surface || '#0b0b10',
    transparent: true,
    opacity: 0.85,
  });
  const plane = new Mesh(geometry, material);
  plane.position.z = -0.01; // behind text
  group.add(plane);

  // --- Async texture load (cached resource) ---
  const textureUrl = config.imageUrl;
  let loadedTexture = null;
  if (textureUrl) {
    const texturePromise = ctx.textureLoader.loadTexture(textureUrl);
    texturePromise.then((tex) => {
      loadedTexture = tex;
      material.map = tex;
      material.color.setHex(0xffffff); // remove tint after texture loads
      material.needsUpdate = true;
    }).catch(() => {
      // fallback: keep placeholder color
    });
  }

  // --- Text overlay ---
  if (bodyText) {
    const textColor = config.colors?.paper || '#e8ecf2';
    const fontSize = bodyItem.typography?.fontSize ?? 31; // per spec "body, 31px"
    const textMesh = ctx.fontAtlas.createText(bodyText, {
      fontSize,           // pixels (will be scaled by scene)
      color: textColor,
      align: 'center',
      maxWidthPx: planeWidth * 200, // generous width; let font atlas handle wrapping
      letterSpacingPx: 0.02 * fontSize, // subtle spacing
    });
    // Scale down so text fits comfortably on plane (since font is in px, we scale to scene units)
    // Assume 1 scene unit ≈ 100 px in font atlas (arbitrary, but need to scale)
    const scaleFactor = 1 / 100; // adjust as needed
    textMesh.scale.setScalar(scaleFactor);
    textMesh.position.set(0, 0, 0.01); // slightly in front
    textMesh.userData.isText = true; // for cleanup
    group.add(textMesh);
  }

  // --- Position from config ---
  const pos = config.scenePosition || { x: 0, y: 3, z: 0 };
  group.position.set(pos.x || 0, pos.y || 3, pos.z || 0);
  group.rotation.set(
    config.sceneRotation?.x || 0,
    config.sceneRotation?.y || 0,
    config.sceneRotation?.z || 0
  );
  group.scale.set(
    config.sceneScale?.x ?? 1,
    config.sceneScale?.y ?? 1,
    config.sceneScale?.z ?? 1
  );

  // --- Event handlers (none in spec, but include empty object) ---
  group.userData.handlers = {};

  // --- Cleanup ---
  group.userData.cleanup = () => {
    // Dispose plane geometry and material
    geometry.dispose();
    material.dispose();
    // Dispose loaded texture
    if (loadedTexture) {
      loadedTexture.dispose();
    }
    // Dispose text children (font atlas provides cleanup methods? usually nothing to dispose)
    group.children.forEach(child => {
      if (child.userData.isText && child.geometry) {
        child.geometry.dispose();
        if (child.material) {
          child.material.dispose();
        }
      }
    });
    // No GSAP timelines active (no animations in this node)
  };

  return group;
}
